public void rotateLeft(int[] nums) {
    if (nums.length <= 1) return;
    int first = nums[0];
    for (int i = 0; i < nums.length - 1; i++) {
        nums[i] = nums[i + 1];
    }
    nums[nums.length - 1] = first;
}

